// Des: Unit tests for arming probes from specs
// Flo: arm each type > assert fields or exact error
// I/O: type + spec text > Prob or ArmzErro
// ===================================================================
const std = @import("std"); const builtin = @import("builtin"); const modu = @import("ev-task-prob.zig");
const tszz = std.testing; const Prob = modu.Prob; const Kind = modu.Kind; const Cond = modu.Cond; const ArmzErro = modu.ArmzErro; const CF = modu.CF; const probArmz = modu.probArmz; const probTypeChec = modu.probTypeChec; const sizePars = modu.sizePars; const duraPars = modu.duraPars; const statPars = modu.statPars; const procRunn = modu.procRunn;
var test_iozz_impl = std.Io.Threaded.init_single_threaded; const iozz: std.Io = test_iozz_impl.io();
fn edge(prob: *Prob, read: Cond) bool { prob.poll_coun += 1; const prev = prob.last; prob.last = read; if (read != .onzz) return false; if (prev != .offz) return false; return true; }
test "probTypeChec covers exactly the 8 S5 types" { for ([_][]const u8{ "live", "disk", "mail", "idle", "powe", "proc", "tcpr", "webs" }) |kind| { try tszz.expect(probTypeChec(kind)); } for ([_][]const u8{ "cron", "puls", "once", "sola", "boot", "hand", "link", "loop", "even", "flag", "queu" }) |kind| { try tszz.expect(!probTypeChec(kind)); } }
test "tcpr: host:port, bare port, and IPv6 brackets" { const aaaa = try probArmz("tcpr", "127.0.0.1:3000"); try tszz.expectEqualStrings("127.0.0.1", aaaa.host); try tszz.expectEqual(@as(u16, 3000), aaaa.port); const bbbb = try probArmz("tcpr", "3010"); try tszz.expectEqualStrings("127.0.0.1", bbbb.host); try tszz.expectEqual(@as(u16, 3010), bbbb.port); const cccc = try probArmz("tcpr", "[::1]:8080"); try tszz.expectEqualStrings("::1", cccc.host); try tszz.expectEqual(@as(u16, 8080), cccc.port); const dddd = try probArmz("tcpr", "example.com:443"); try tszz.expectEqualStrings("example.com", dddd.host); }
test "tcpr: bad specs are rejected at arm time" { try tszz.expectError(ArmzErro.NeedsSpec, probArmz("tcpr", null)); try tszz.expectError(ArmzErro.NeedsSpec, probArmz("tcpr", "   ")); try tszz.expectError(ArmzErro.BadPort, probArmz("tcpr", "host:0")); try tszz.expectError(ArmzErro.BadPort, probArmz("tcpr", "host:99999")); try tszz.expectError(ArmzErro.BadPort, probArmz("tcpr", "host:abc")); try tszz.expectError(ArmzErro.BadHost, probArmz("tcpr", "notaport")); try tszz.expectError(ArmzErro.BadHost, probArmz("tcpr", ":3000")); }
test "webs: scheme optional, port defaults to 80, path defaults to /" { const aaaa = try probArmz("webs", "http://localhost:3000/health"); try tszz.expectEqualStrings("localhost", aaaa.host); try tszz.expectEqual(@as(u16, 3000), aaaa.port); try tszz.expectEqualStrings("/health", aaaa.path); const bbbb = try probArmz("webs", "example.com"); try tszz.expectEqual(@as(u16, 80), bbbb.port); try tszz.expectEqualStrings("/", bbbb.path); const cccc = try probArmz("webs", "http://example.com/a/b?c=d"); try tszz.expectEqualStrings("/a/b?c=d", cccc.path); }
test "webs: https is REJECTED at arm time, not silently broken at poll time" { try tszz.expectError(ArmzErro.BadUrl, probArmz("webs", "https://example.com")); try tszz.expectError(ArmzErro.BadUrl, probArmz("webs", "HTTPS://example.com/x")); }
test "disk: operator picks the direction, and it is mandatory" { const aaaa = try probArmz("disk", "C:\\<10GB"); try tszz.expectEqualStrings("C:\\", aaaa.path); try tszz.expectEqual(@as(u64, 10 * 1024 * 1024 * 1024), aaaa.thre); try tszz.expect(aaaa.belo); const bbbb = try probArmz("disk", "E:\\ > 500MB"); try tszz.expectEqualStrings("E:\\", bbbb.path); try tszz.expectEqual(@as(u64, 500 * 1024 * 1024), bbbb.thre); try tszz.expect(!bbbb.belo); try tszz.expectError(ArmzErro.BadSize, probArmz("disk", "C:\\ 10GB")); try tszz.expectError(ArmzErro.BadSize, probArmz("disk", "C:\\<nope")); try tszz.expectError(ArmzErro.NeedsSpec, probArmz("disk", "<10GB")); }
test "proc/alive: an image name, never a path" { const aaaa = try probArmz("proc", "node.exe"); try tszz.expectEqual(Kind.proc, aaaa.kind); try tszz.expectEqualStrings("node.exe", aaaa.name); const bbbb = try probArmz("live", "auto-task.exe"); try tszz.expectEqual(Kind.aliv, bbbb.kind); try tszz.expectError(ArmzErro.BadProc, probArmz("proc", "C:\\Windows\\notepad.exe")); try tszz.expectError(ArmzErro.BadProc, probArmz("live", "/usr/bin/node")); }
test "idle + powe specs" { const idle = try probArmz("idle", "15m"); try tszz.expectEqual(@as(u64, 900_000), idle.thre); try tszz.expectEqual(@as(i64, CF.poll_fast_msec), idle.poll_msec); const bat1 = try probArmz("powe", "battery"); try tszz.expect(bat1.batt_onzz); const acz1 = try probArmz("powe", "ac"); try tszz.expect(!acz1.batt_onzz); const plug = try probArmz("powe", "PLUGGED"); try tszz.expect(!plug.batt_onzz); try tszz.expectError(ArmzErro.BadPowerSpec, probArmz("powe", "maybe")); try tszz.expectError(ArmzErro.BadDuration, probArmz("idle", "soon")); }
test "mail arms as unwired: listed, explained, never fires" { var prob = try probArmz("mail", null); try tszz.expect(prob.unwi); try tszz.expect(prob.unwi_whyz.len > 0); try tszz.expectEqualStrings("unwired", prob.statName()); var indx: u32 = 0; while (indx < 500) : (indx += 1) try tszz.expect(!prob.duez(iozz, @intCast(indx * 60_000))); }
